function reportAnalysisSummaryHtml() { const regions=[...new Set(bones.map(bone=>bone.region))].sort((a,b)=>a.localeCompare(b,'es')); const regionRows=regions.map(region=>{const items=bones.filter(bone=>bone.region===region);const reviewed=items.filter(bone=>(state.status[bone.id]||'not_recorded')!=='not_recorded').length;const completeness=reviewed?Math.round(items.filter(bone=>(state.status[bone.id]||'not_recorded')!=='not_recorded').reduce((sum,bone)=>sum+(Number(state.completeness[bone.id])||0),0)/reviewed):0;return `<tr><td>${escapeHtml(region)}</td><td>${reviewed}/${items.length}</td><td>${completeness}%</td></tr>`;}).join(''); const detailValues=(details)=>Object.values(details||{}).map(detail=>detail?.type||(detailHasValue(detail)?'structured':'')); const taphonomy=[...new Set([...Object.values(state.taphonomy||{}).flat(),...detailValues(state.taphonomyDetails)])].filter(Boolean); const pathology=[...new Set([...Object.values(state.pathology||{}).flat(),...detailValues(state.pathologyDetails)])].filter(Boolean); const preservation=Object.entries(preservationNames).map(([key,label])=>`<li>${escapeHtml(label)}: ${bones.filter(bone=>(state.preservation[bone.id]||'not_evaluated')===key).length}</li>`).join(''); return `<h2>Representación regional</h2><table><thead><tr><th>Región</th><th>Revisados</th><th>Conservación media</th></tr></thead><tbody>${regionRows}</tbody></table><h2>Conservación</h2><ul>${preservation}</ul><p>Tafonomía registrada: <strong>${taphonomy.length}</strong> alteraciones únicas. Patología/trauma registrado: <strong>${pathology.length}</strong> anotaciones únicas.</p>`; }
function analysisReportHtml() { const analysis=calculateOsteoAnalysis(bones,state); const measurementRows=Object.entries(state.measurements||{}).filter(([,value])=>value&&Object.values(value).some(item=>item!=null&&item!=='')); const landmarkRows=Object.entries(state.landmarks||{}).flatMap(([boneId,points])=>(Array.isArray(points)?points:[]).map(point=>({boneId,point}))); return `<h2>Análisis cuantitativo</h2><p>NISP: <strong>${analysis.nisp.value}</strong> · MNE: <strong>${analysis.mne.value}</strong> · MNI: <strong>${analysis.mni.value}</strong> · Individuos: <strong>${analysis.individuals.value}</strong></p><dl><dt>Método NISP</dt><dd>${escapeHtml(analysis.nisp.method)}</dd><dt>Método MNE</dt><dd>${escapeHtml(analysis.mne.method)}</dd><dt>Método MNI</dt><dd>${escapeHtml(analysis.mni.method)}</dd></dl><h2>Detalle osteométrico</h2><table><thead><tr><th>Elemento</th><th>Longitud</th><th>Anchura</th><th>Altura</th><th>Diámetro</th><th>Unidad</th></tr></thead><tbody>${measurementRows.map(([boneId,value])=>`<tr><td>${escapeHtml(bones.find(bone=>bone.id===boneId)?.es||boneId)}</td><td>${escapeHtml(value.length)}</td><td>${escapeHtml(value.width)}</td><td>${escapeHtml(value.height)}</td><td>${escapeHtml(value.diameter)}</td><td>${escapeHtml(value.unit||'mm')}</td></tr>`).join('')||'<tr><td colspan="6">Sin mediciones registradas</td></tr>'}</tbody></table><p>Landmarks registrados: <strong>${landmarkRows.length}</strong>.</p>`; }
function photosReportHtml() { const photos=Object.entries(state.photos||{}).flatMap(([scope,items])=>(Array.isArray(items)?items:[]).map(photo=>({scope,photo,source:safePhotoSource(photo?.dataUrl)}))).filter(({source})=>source); if(!photos.length)return '<h2>Fotografías</h2><p>Sin fotografías locales seleccionadas.</p>'; return `<h2>Fotografías locales</h2><div class="report-photos">${photos.map(({scope,photo,source})=>`<figure><img src="${source}" alt="${escapeHtml(photo.name||'Fotografía')}"/><figcaption>${escapeHtml(photo.name||'Fotografía')} · ${escapeHtml(scope)}</figcaption></figure>`).join('')}</div>`; }
function observationsReportHtml() { const ids=new Set([...Object.keys(state.taphonomy||{}), ...Object.keys(state.pathology||{}), ...Object.keys(state.taphonomyDetails||{}), ...Object.keys(state.pathologyDetails||{})]); const rows=[...ids].map(boneId=>{const bone=bones.find(item=>item.id===boneId); const taphonomy=state.taphonomyDetails?.[boneId]||{}; const pathology=state.pathologyDetails?.[boneId]||{}; const legacyTaphonomy=Array.isArray(state.taphonomy?.[boneId])?state.taphonomy[boneId].join('; '):''; const legacyPathology=Array.isArray(state.pathology?.[boneId])?state.pathology[boneId].join('; '):''; const taphonomyText=[taphonomy.type,taphonomy.description,taphonomy.position,taphonomy.extent,taphonomy.observations,legacyTaphonomy].filter(Boolean).join(' · '); const pathologyText=[pathology.type,pathology.description,pathology.position,pathology.extent,pathology.observations,legacyPathology].filter(Boolean).join(' · '); return `<tr><td>${escapeHtml(bone?.es||boneId)}</td><td>${escapeHtml(taphonomyText||'—')}</td><td>${escapeHtml(pathologyText||'—')}</td></tr>`; }).join(''); return `<h2>Tafonomía y patología / trauma</h2><table><thead><tr><th>Elemento</th><th>Alteraciones tafonómicas</th><th>Patología / trauma</th></tr></thead><tbody>${rows||'<tr><td colspan="3">Sin observaciones registradas</td></tr>'}</tbody></table>`; }
function reportContextHtml() { const report=state.report||{}; const fields=reportContextFields.filter(([key])=>report[key]).map(([key,label])=>`<dt>${label}</dt><dd>${escapeHtml(report[key])}</dd>`).join(''); return fields?`<h2>Ficha de contexto</h2><dl>${fields}</dl>`:''; }
