function printReport() { saveReportData(); const win=window.open('','_blank'); if(!win)return; const totalWeight=bones.reduce((sum,b)=>sum+(Number.isFinite(Number(state.weights[b.id]))?Number(state.weights[b.id]):0),0); const indeterminateWeight=(state.indeterminateFragments||[]).reduce((sum,item)=>sum+(Number.isFinite(Number(item.weight))&&Number(item.weight)>=0?Number(item.weight):0),0); const indeterminateCount=(state.indeterminateFragments||[]).length; const html=reportHtml().replace('</body>',`${reportAnalysisSummaryHtml()}<p><strong>Peso total registrado (identificado):</strong> ${totalWeight.toFixed(2)} g</p><p><strong>Fragmentos indeterminados:</strong> ${indeterminateCount} · ${indeterminateWeight.toFixed(2)} g (excluidos de NISP/MNE/MNI)</p></body>`); win.document.write(html); win.document.close(); win.focus(); setTimeout(()=>win.print(),250); }
function photoKey() { const scope=document.querySelector('#photo-scope')?.value||state.photoScope||'bone'; if(scope==='bone')return state.selected; const target=document.querySelector('#photo-target')?.value.trim()||state.photoTargetId||state.report?.individual||'IND-LOCAL'; return `${scope}:${target}`; }
function safePhotoSource(value) { const source=String(value??''); return /^data:image\/(?:png|jpeg|jpg|webp|gif);base64,/i.test(source) ? escapeHtml(source) : ''; }
function renderPhotos() { const list=document.querySelector('#photo-list'); if(!list)return; const key=photoKey(); const photos=state.photos[key]||[]; list.innerHTML=photos.map((photo,index)=>{const source=safePhotoSource(photo.dataUrl);return source?`<figure><img src="${source}" alt="${escapeHtml(photo.name)}"><figcaption>${escapeHtml(photo.name)}<button data-remove-photo="${index}">×</button></figcaption></figure>`:'';}).join(''); list.querySelectorAll('[data-remove-photo]').forEach(button=>button.onclick=()=>{const previous=structuredClone(state.photos[key]||[]);photos.splice(+button.dataset.removePhoto,1);recordInventoryFieldChange(key,'photos',previous,photos,'photo_remove');renderPhotos();saveLocal();}); }
function addPhotos(files) { const key=photoKey(); if(!state.photos[key])state.photos[key]=[]; [...files].filter(file=>file.type.startsWith('image/')).forEach(file=>{if(file.size>12*1024*1024){document.querySelector('#toast').textContent=`Foto rechazada por tamaño: ${file.name}`;return;} const reader=new FileReader();reader.onload=()=>{const image=new Image();image.onload=()=>{const max=1800;const scale=Math.min(1,max/Math.max(image.naturalWidth,image.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const type=file.type==='image/png'?'image/png':'image/jpeg';const dataUrl=canvas.toDataURL(type,type==='image/jpeg'?0.82:undefined);const previous=structuredClone(state.photos[key]||[]);state.photos[key].push({name:file.name,type,dataUrl,width:canvas.width,height:canvas.height});recordInventoryFieldChange(key,'photos',previous,state.photos[key],'photo_add');renderPhotos();saveLocal();};image.onerror=()=>{document.querySelector('#toast').textContent=`Foto no válida: ${file.name}`;};image.src=reader.result;};reader.readAsDataURL(file);}); }
async function protectLocalStorage() { const status=document.querySelector('#storage-status'); if(!status||!navigator.storage?.persist) return; try { let persisted=await navigator.storage.persisted(); if(!persisted) persisted=await navigator.storage.persist(); status.textContent=persisted?'Datos locales protegidos':'Datos locales'; status.classList.toggle('protected',persisted); } catch { status.textContent='Datos locales'; } }
async function runPwaDiagnostics() { const list=document.querySelector('#pwa-diagnostics-status'); if(!list)return; const checks=[]; const add=(label,ok,detail)=>checks.push(`<li class="${ok?'ok':'pending'}"><span aria-hidden="true">${ok?'✓':'○'}</span> ${label}: ${detail}</li>`); const hasServiceWorker='serviceWorker' in navigator; if(!hasServiceWorker){add('Service Worker',false,'no disponible');} else { const registration=await navigator.serviceWorker.getRegistration(); add('Service Worker',!!registration,registration?'registrado':'pendiente'); } let shellCached=false; try { const cache=globalThis.caches && await caches.open('osteo3d-shell-v7'); const shellEntries=['./index.html','./manifest.json','./models/manifest.json','./models/sources.json','./icons/osteo3d-192.png','./icons/osteo3d-512.png']; const results=await Promise.all(shellEntries.map(path=>cache?.match(path))); shellCached=results.every(Boolean); } catch {} add('Shell offline',shellCached,shellCached?'HTML, datos e iconos en caché':'pendiente de primera carga'); let manifestIcons=false; try { const manifestResponse=await fetch('./manifest.json',{cache:'no-store'}); const manifest=manifestResponse.ok?await manifestResponse.json():null; const icons=Array.isArray(manifest?.icons)?manifest.icons:[]; const results=await Promise.all(icons.map(icon=>fetch(icon.src,{cache:'no-store'}).then(response=>response.ok).catch(()=>false))); manifestIcons=manifestResponse.ok && icons.some(icon=>icon.type==='image/png') && icons.length>=2 && results.every(Boolean); } catch {} add('Iconos PWA',manifestIcons,'manifiesto e iconos '+(manifestIcons?'disponibles':'pendientes')); const indexedDbAvailable='indexedDB' in globalThis; const localStorageAvailable=(() => { try { const key='osteo3d-storage-check'; localStorage.setItem(key,'1'); localStorage.removeItem(key); return true; } catch { return false; } })(); let persisted=false; try { persisted=!!navigator.storage?.persisted && await navigator.storage.persisted(); } catch {} const localStorageDetail=persisted?'persistencia protegida':indexedDbAvailable?'IndexedDB disponible':localStorageAvailable?'respaldo localStorage disponible':'almacenamiento local no disponible'; add('Datos locales',persisted||indexedDbAvailable||localStorageAvailable,localStorageDetail); const standalone=globalThis.matchMedia?.('(display-mode: standalone)').matches || globalThis.navigator?.standalone; const ios=/iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform==='MacIntel' && navigator.maxTouchPoints>1); const install=document.querySelector('#install-app'); const installReady=!!deferredInstallPrompt && !standalone; if(standalone){ add('Instalación',true,'modo instalado'); } else if(installReady){ add('Instalación',true,'disponible en este navegador'); if(install) install.hidden=false; } else if(ios){ add('Instalación',false,'Safari: Compartir → Añadir a pantalla de inicio'); } else { add('Instalación',false,'navegador (aún no ofrecida)'); } list.innerHTML=checks.join(''); }
async function registerPwa() { if(!('serviceWorker' in navigator)) return; const registration=await navigator.serviceWorker.register('./sw.js'); protectLocalStorage().catch(()=>{}); const updateActions=document.querySelector('#update-actions'); const updateButton=document.querySelector('#update-app'); const dismissButton=document.querySelector('#dismiss-update'); let updateRequested=false; const hideUpdate=()=>{if(updateActions)updateActions.hidden=true;}; const showUpdate=()=>{if(updateActions)updateActions.hidden=false;}; if(updateButton) updateButton.onclick=async()=>{ await saveLocal({ notify:false }); updateRequested=true; registration.waiting?.postMessage({type:'SKIP_WAITING'}); }; if(dismissButton) dismissButton.onclick=hideUpdate; if(registration.waiting) showUpdate(); registration.addEventListener('updatefound',()=>{const worker=registration.installing; worker?.addEventListener('statechange',()=>{if(worker.state==='installed' && navigator.serviceWorker.controller) showUpdate();});}); navigator.serviceWorker.addEventListener('controllerchange',()=>{if(updateRequested) window.location.reload();}); window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;const install=document.querySelector('#install-app');if(install){install.hidden=false;install.onclick=async()=>{install.hidden=true;await deferredInstallPrompt.prompt();deferredInstallPrompt=null;runPwaDiagnostics();};} runPwaDiagnostics();}); window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;const install=document.querySelector('#install-app');if(install)install.hidden=true;runPwaDiagnostics();}); }
let modelPackagePanelRequest = 0;
function updateModelPackagePanel() { const statusElement=document.querySelector('#model-package-status'); const sizeElement=document.querySelector('#model-package-size'); const cacheElement=document.querySelector('#model-package-cache'); const action=document.querySelector('#model-package-action'); const remove=document.querySelector('#model-package-remove'); if(!statusElement||!action||!remove)return; const request=++modelPackagePanelRequest; if(!modelManifest){statusElement.textContent='Manifiesto GLB no disponible; se mantienen marcadores geométricos de desarrollo.';sizeElement.textContent='Tamaño aproximado: no disponible';cacheElement.textContent='Caché offline: no disponible';action.textContent='No disponible';action.disabled=true;remove.disabled=true;return;} const summary=modelPackageSummary(modelManifest,state.profile,bones); const labels={placeholder:'Pendiente de incorporar assets licenciados',partial:'Disponible parcialmente',ready:'Disponible para descarga',missing:'Perfil no definido'}; statusElement.textContent=`${summary.expected} elementos · ${labels[summary.status]||summary.status}.`; sizeElement.textContent=`Tamaño aproximado: ${formatPackageSize(summary.approximateSizeMb)}`; cacheElement.textContent='Caché offline: comprobando…'; action.disabled=!['ready','partial'].includes(summary.status); action.textContent=action.disabled?'No disponible':'Descargar paquete offline'; action.title=action.disabled?'Este perfil aún no tiene modelos GLB licenciados publicados.':'Guardar los modelos GLB del perfil en la caché offline.'; remove.disabled=true; getModelPackageCacheStatus(modelManifest,state.profile,bones).then(result=>{if(request!==modelPackagePanelRequest)return; cacheElement.textContent=`Caché offline: ${result.cached}/${result.expected} recursos`; remove.disabled=result.cached===0;}).catch(()=>{if(request===modelPackagePanelRequest)cacheElement.textContent='Caché offline: no disponible';}); }
async function downloadSelectedModelPackage() { const action=document.querySelector('#model-package-action'); const toast=document.querySelector('#toast'); if(!modelManifest||action?.disabled)return; const original=action.textContent; action.disabled=true; action.textContent='Descargando…'; try { const result=await downloadModelPackage(modelManifest,state.profile,bones); toast.textContent=`Paquete ${state.profile} guardado offline · ${result.downloaded} modelos`; } catch(error) { toast.textContent=error.message||'No se pudo descargar el paquete 3D.'; } finally { updateModelPackagePanel(); if(action && !action.disabled && action.textContent===original) action.textContent=original; } }
async function removeSelectedModelPackage() { const remove=document.querySelector('#model-package-remove'); const toast=document.querySelector('#toast'); if(!modelManifest||remove?.disabled)return; if(!await requestConfirmation(`Se eliminarán los modelos GLB offline del perfil ${state.profile}. ¿Continuar?`))return; remove.disabled=true; try { const result=await removeModelPackage(modelManifest,state.profile,bones); toast.textContent=`Paquete ${state.profile} eliminado · ${result.removed} recursos`; } catch(error) { toast.textContent=error.message||'No se pudo eliminar el paquete 3D.'; } finally { updateModelPackagePanel(); } }
async function importLocalModelFiles(files) { const toast=document.querySelector('#toast'); if(!files.length)return; if(!await requestConfirmation(`La importación reemplazará los modelos GLB locales coincidentes del perfil ${state.profile}. ¿Continuar?`))return; try { const result=await importModelPackageFiles(state.profile,files,bones.map(bone=>bone.id)); await loadAvailableProfileModels(); updateModelPackagePanel(); toast.textContent=`GLB locales importados · ${result.importedCount}${result.rejectedCount ? ` · rechazados ${result.rejectedCount}` : ''}`; } catch(error) { toast.textContent=error.message||'No se pudieron importar los modelos GLB.'; } }
async function importCustomModel(file) { const toast=document.querySelector('#toast'); const bone=bones.find(item=>item.id===state.selected); if(!file||!bone||!THREE||!group)return; if(!await requestConfirmation(`El modelo local se asociará a ${bone.es} y se guardará offline. ¿Continuar?`))return; try { const loaded=await loadLocalModel(THREE,file); const root=loaded.scene || loaded; addLoadedModelRoot(root,bone,'custom'); state.customModels ||= {}; state.customModels[state.profile] ||= {}; let cached=true; try { await cacheCustomModelFile(state.profile,bone.id,file); } catch { cached=false; } state.customModels[state.profile][bone.id]={fileName:file.name,format:String(file.name).split('.').pop().toLowerCase(),cached,updatedAt:new Date().toISOString()}; await saveLocal({notify:false}); selectBone(bone.id); toast.textContent=`Modelo propio cargado · ${bone.es}${cached?' · guardado offline':' · solo sesión actual'}`; } catch(error) { toast.textContent=error.message||'No se pudo cargar el modelo propio.'; } }
async function verifyModelPackages() { try { modelManifest=await loadModelManifest(); modelSourceRegistry=await loadModelSourceRegistry(modelManifest); const statuses=Object.values(modelManifest.profiles).map(profile=>profile.asset_status); const ready=statuses.filter(status=>status==='ready').length; const registered=Object.values(modelSourceRegistry.profiles || {}).filter(source=>source.source_status!=='pending').length; document.querySelector('.side-note').textContent=`Manifiesto GLB válido · ${ready}/${statuses.length} perfiles con assets documentados · registro de fuentes válido (${registered} con fuente publicada). Las geometrías actuales son marcadores de desarrollo.`; } catch { modelSourceRegistry=null; if (!modelManifest) document.querySelector('.side-note').textContent='Manifiesto GLB o registro de fuentes no disponible; se mantienen marcadores geométricos de desarrollo.'; else document.querySelector('.side-note').textContent='Manifiesto GLB válido, pero el registro de fuentes necesita revisión; se mantienen marcadores geométricos de desarrollo.'; } updateModelPackagePanel(); }
