function matchesPaintRegion(bone, target) { if (target === 'cervical') return /^c(?:1_atlas|[2-7])$/.test(bone.id) || bone.id === 'cervical_indeterminate'; if (target === 'thoracic') return /^t(?:[1-9]|1[0-2])$/.test(bone.id) || bone.id === 'thoracic_indeterminate'; if (target === 'lumbar') return /^l[1-5]$/.test(bone.id) || bone.id === 'lumbar_indeterminate'; if (target === 'pelvis') return bone.region === 'Pelvis'; const groups={upper:['Extremidad superior'],hand:['Manos'],lower:['Extremidad inferior'],foot:['Pies']}; for(const [prefix,regions] of Object.entries(groups)){if(target.startsWith(prefix+'_')) return regions.includes(bone.region) && ((target.endsWith('_left') && bone.side==='Izquierda') || (target.endsWith('_right') && bone.side==='Derecha'));} return bone.region === target; }
