setTimeout(() => { if (modelManifest) loadAvailableProfileModels(); }, 800);
function updateConservationMap() { const target=document.querySelector('#conservation-map'); if(!target)return; const categories=[['excellent','Excelente','#2f855a'],['good','Buena','#68d391'],['regular','Regular','#ecc94b'],['poor','Mala','#ed8936'],['very_poor','Muy mala','#e53e3e'],['very_fragmented','Muy fragmentado','#9b2c2c'],['not_evaluated','No evaluada','#a0aec0'],['not_evaluable','No evaluable','#718096']]; const visible=bones.filter(matchesFilters); target.innerHTML=categories.map(([key,label,color])=>{const items=visible.filter(b=>(state.preservation[b.id]||'not_evaluated')===key);const average=items.length?Math.round(items.reduce((sum,b)=>sum+(Number(state.completeness[b.id])||0),0)/items.length):0;return `<div class="conservation-row"><span>${label}</span><strong>${items.length}</strong><div class="conservation-bar"><i style="width:${visible.length?items.length/visible.length*100:0}%;background:${color}"></i></div><small>${average}% medio</small></div>`;}).join(''); }
function updateFragmentationMap() { const target=document.querySelector('#fragmentation-map'); if(!target)return; const visible=bones.filter(matchesFilters); const regions=[...new Set(visible.map(bone=>bone.region))].sort((a,b)=>a.localeCompare(b,'es')); target.innerHTML=`<strong>Fragmentación</strong>${regions.map(region=>{const items=visible.filter(bone=>bone.region===region);const identified=items.filter(bone=>['present','fragmentary'].includes(state.status[bone.id]||'not_recorded'));const fragments=identified.reduce((sum,bone)=>sum+Math.max(0,Number(state.fragments[bone.id])||0),0);const average=identified.length?(fragments/identified.length).toFixed(2):'0.00';return `<div class="fragmentation-row"><span>${escapeHtml(region)}</span><strong>${fragments}</strong><small>${identified.length} elementos · ${average} frag./elemento</small></div>`;}).join('')||'<small>Sin elementos para los filtros activos.</small>'}`; }
function updateRegionalStats() { const target=document.querySelector('#regional-stats'); if(!target)return; const regions=[...new Set(bones.map(b=>b.region))].sort((a,b)=>a.localeCompare(b,'es')); target.innerHTML=`<table class="analysis-table"><thead><tr><th>Región</th><th>Revisados</th><th>Presentes</th><th>Fragmentarios</th><th>Conservación media</th></tr></thead><tbody>${regions.map(region=>{const items=bones.filter(b=>b.region===region&&matchesFilters(b));const reviewed=items.filter(b=>(state.status[b.id]||'not_recorded')!=='not_recorded').length;const present=items.filter(b=>state.status[b.id]==='present').length;const fragmentary=items.filter(b=>state.status[b.id]==='fragmentary').length;const average=reviewed?Math.round(items.filter(b=>(state.status[b.id]||'not_recorded')!=='not_recorded').reduce((sum,b)=>sum+(Number(state.completeness[b.id])||0),0)/reviewed):0;return `<tr><td>${region}</td><td>${reviewed}/${items.length}</td><td>${present}</td><td>${fragmentary}</td><td>${average}%</td></tr>`;}).join('')}</tbody></table>`; }
function updateSideStats() { const target=document.querySelector('#side-stats'); if(!target)return; const visible=bones.filter(matchesFilters); const sides=[['Izquierda','left'],['Derecha','right'],['—','none']]; target.innerHTML=`<strong>Representación por lateralidad</strong>${sides.map(([label])=>{const items=visible.filter(bone=>bone.side===label);const reviewed=items.filter(bone=>(state.status[bone.id]||'not_recorded')!=='not_recorded').length;const present=items.filter(bone=>state.status[bone.id]==='present').length;const fragmentary=items.filter(bone=>state.status[bone.id]==='fragmentary').length;return `<div class="side-stat-row"><span>${label}</span><strong>${reviewed}/${items.length}</strong><small>${present} presentes · ${fragmentary} fragmentarios</small></div>`;}).join('')}`; }
function updateQuantificationSummary() { const target=document.querySelector('#quantification-summary'); if(!target)return; const analysis=calculateOsteoAnalysis(bones.filter(matchesFilters),state); target.innerHTML=`<strong>NISP · MNE · MNI</strong><div class="quantification-values"><span><b>${analysis.nisp.value}</b>NISP</span><span><b>${analysis.mne.value}</b>MNE</span><span><b>${analysis.mni.value}</b>MNI</span></div><small>${escapeHtml(analysis.nisp.method)}</small><small>${escapeHtml(analysis.mne.method)}</small><small>${escapeHtml(analysis.mni.method)}</small>`; }
setTimeout(()=>{ const summary=document.querySelector('#stats-summary'); if(summary&&!document.querySelector('#conservation-map')){summary.insertAdjacentHTML('afterend','<div id="conservation-map" class="conservation-map" aria-label="Mapa de conservación esquelética"></div>'); updateConservationMap(); setInterval(updateConservationMap,1000); } },0);
setTimeout(()=>{ const summary=document.querySelector('#conservation-map'); if(summary&&!document.querySelector('#fragmentation-map')){summary.insertAdjacentHTML('afterend','<div id="fragmentation-map" class="fragmentation-map" aria-label="Resumen descriptivo de fragmentación"></div>'); updateFragmentationMap(); setInterval(updateFragmentationMap,1000); } },0);
setTimeout(()=>{ const summary=document.querySelector('#regional-stats'); if(summary&&!document.querySelector('#side-stats')){summary.insertAdjacentHTML('afterend','<div id="side-stats" class="side-stats" aria-label="Representación por lateralidad"></div>'); updateSideStats(); setInterval(updateSideStats,1000); } },0);
setTimeout(()=>{ const summary=document.querySelector('#side-stats'); if(summary&&!document.querySelector('#quantification-summary')){summary.insertAdjacentHTML('afterend','<div id="quantification-summary" class="quantification-summary" aria-label="NISP MNE MNI"></div>'); updateQuantificationSummary(); setInterval(updateQuantificationSummary,1000); } },0);
setTimeout(()=>{ const summary=document.querySelector('#stats-summary'); if(summary&&!document.querySelector('#regional-stats')){summary.insertAdjacentHTML('afterend','<div id="regional-stats" aria-label="Representación estadística regional"></div>'); updateRegionalStats(); setInterval(updateRegionalStats,1000); } },0);
function updateWeightSummary() { const target=document.querySelector('#weight-summary'); if(!target)return; const totals=new Map(); let total=0; let recorded=0; bones.forEach(bone=>{const weight=Number(state.weights[bone.id]); if(!Number.isFinite(weight)||weight<0)return; total+=weight; recorded+=1; totals.set(bone.region,(totals.get(bone.region)||0)+weight);}); const indeterminateWeight=(state.indeterminateFragments||[]).reduce((sum,item)=>sum+(Number.isFinite(Number(item.weight))&&Number(item.weight)>=0?Number(item.weight):0),0); const regions=[...totals.entries()].sort((a,b)=>a[0].localeCompare(b[0],'es')).map(([region,weight])=>`${region}: ${weight.toFixed(2)} g`).join(' · '); target.textContent=`Peso identificado: ${total.toFixed(2)} g en ${recorded}/${bones.length} elementos${indeterminateWeight?` · Peso indeterminado: ${indeterminateWeight.toFixed(2)} g`:''}${regions?` · ${regions}`:''}`; }
setTimeout(()=>{ const summary=document.querySelector('#conservation-map'); if(summary&&!document.querySelector('#weight-summary')){summary.insertAdjacentHTML('afterend','<p id="weight-summary" class="weight-summary" aria-live="polite"></p>'); updateWeightSummary(); setInterval(updateWeightSummary,1000); } },0);
setTimeout(() => document.querySelector('#new-project')?.addEventListener('click', () => { state.weights = {}; state.indeterminateFragments = []; state.photoScope = 'bone'; state.photoTargetId = ''; }), 0);
document.querySelector('#reset').addEventListener('click',()=>{state.comparisonProfile='';setComparisonProfile('');});
document.querySelector('#new-project')?.addEventListener('click',()=>{state.comparisonProfile='';setComparisonProfile('');});
document.querySelector('.range-label')?.insertAdjacentHTML('afterend','<button id="explosion-play" class="secondary-action" aria-pressed="false">Reproducir despliegue</button>');
document.querySelector('#explosion-play').onclick=()=>{state.explosionAnimating=!state.explosionAnimating;const button=document.querySelector('#explosion-play');button.setAttribute('aria-pressed',String(state.explosionAnimating));button.textContent=state.explosionAnimating?'Pausar despliegue':'Reproducir despliegue';};
document.querySelector('#reset').addEventListener('click',()=>{state.explosionAnimating=false;const button=document.querySelector('#explosion-play');if(button){button.setAttribute('aria-pressed','false');button.textContent='Reproducir despliegue';}});
document.querySelector('#clear-filters')?.addEventListener('click',()=>{state.filters.preservation='all';state.filters.type='all';const preservation=document.querySelector('#filter-preservation');const type=document.querySelector('#filter-type');if(preservation)preservation.value='all';if(type)type.value='all';});
